	                Type = "Encantamiento — Saga",
	                Flavor = nil,
	                ImageUrl = "http://gatherer.wizards.com/Handlers/Image.ashx?multiverseid=617503&type=card",
	                Language = "Spanish",
	                Identifiers = {
	                    ScryfallId = "ce7346d7-7497-461b-9473-1959097b0840",
	                    MultiverseId = 617503
